import json
import numpy as np

class NumpyEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.bool_, bool)):
            return bool(obj)
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return float(obj)
        return super().default(obj)

# Re-run the computation but with proper JSON encoding
from scipy.stats import binomtest
from collections import Counter

PW_DATA = "/root/symb_invariant_consensus/data/proofwriter_full.json"
MISTRAL_VOTES = "/root/symb_invariant_consensus/data/mistral_pw600_sc_votes.json"
D116 = "/root/symb_invariant_consensus/results/d116_qwen3_pw_deberta_large/results.json"
DIR_K = "/root/symb_invariant_consensus/results/dir_k_nli_qwen3_proofwriter/results.json"
PUSH_B = "/root/symb_invariant_consensus/results/push_b_stronger_nli_verifier/results.json"
OUTPUT = "/root/symb_invariant_consensus/results/r11_3verifier_combo.json"
CLASSES = ["True", "False", "Unknown"]
WEIGHTS = [1, 3, 5]

def mcnemar_exact(correct_a, correct_b):
    b = sum(1 for a, bb in zip(correct_a, correct_b) if not a and bb)
    c = sum(1 for a, bb in zip(correct_a, correct_b) if a and not bb)
    n_disc = b + c
    if n_disc == 0:
        return 1.0, b, c
    result = binomtest(min(b, c), n_disc, 0.5)
    return float(result.pvalue), b, c

def bh_correction(p_values):
    n = len(p_values)
    if n == 0:
        return []
    sorted_indices = sorted(range(n), key=lambda i: p_values[i])
    adjusted = [0.0] * n
    for rank, idx in enumerate(sorted_indices, 1):
        adjusted[idx] = p_values[idx] * n / rank
    for i in range(n - 2, -1, -1):
        idx = sorted_indices[i]
        next_idx = sorted_indices[i + 1]
        adjusted[idx] = min(adjusted[idx], adjusted[next_idx])
    return [min(p, 1.0) for p in adjusted]

def sc_answer(votes):
    if not votes:
        return None
    return max(CLASSES, key=lambda x: votes.get(x, 0))

pw = json.load(open(PW_DATA))
gt = {p["id"]: p["answer"] for p in pw}
pids = sorted(gt.keys())
n = len(pids)

raw_votes = json.load(open(MISTRAL_VOTES))
mistral_votes = {pid: {"True": v[0], "False": v[1], "Unknown": v[2]} for pid, v in raw_votes.items()}
mistral_sc_answers = {pid: sc_answer(mistral_votes.get(pid, {})) for pid in pids}
sc_correct = [mistral_sc_answers[pid] == gt[pid] for pid in pids]
sc_acc = sum(sc_correct) / n

d116 = json.load(open(D116))
dirk = json.load(open(DIR_K))
pushb = json.load(open(PUSH_B))

verifiers_data = {}

# DeBERTa-large-MNLI
d116_pq = d116["per_question"]
dl_preds, dl_probs = {}, {}
for pid in pids:
    if pid in d116_pq:
        dl_preds[pid] = d116_pq[pid]["deberta_pred"]
        dl_probs[pid] = d116_pq[pid]["deberta_probs"]
    else:
        dl_preds[pid] = "Unknown"
        dl_probs[pid] = {"True": 0.0, "False": 0.0, "Unknown": 1.0}
verifiers_data["DeBERTa-large-MNLI"] = {"preds": dl_preds, "probs": dl_probs}

# DeBERTa-base-MNLI
dirk_pq = dirk["per_question"]
db_preds, db_probs = {}, {}
for pid in pids:
    if pid in dirk_pq:
        db_preds[pid] = dirk_pq[pid]["deberta_pred"]
        db_probs[pid] = dirk_pq[pid]["deberta_probs"]
    else:
        db_preds[pid] = "Unknown"
        db_probs[pid] = {"True": 0.0, "False": 0.0, "Unknown": 1.0}
verifiers_data["DeBERTa-base-MNLI"] = {"preds": db_preds, "probs": db_probs}

# DeBERTa-v3-large
pushb_pp = pushb["per_problem"]
dv3_preds, dv3_probs = {}, {}
for pid in pids:
    if pid in pushb_pp:
        dv3_preds[pid] = pushb_pp[pid]["nli_pred"]
        dv3_probs[pid] = pushb_pp[pid]["nli_probs"]
    else:
        dv3_preds[pid] = "Unknown"
        dv3_probs[pid] = {"True": 0.0, "False": 0.0, "Unknown": 1.0}
verifiers_data["DeBERTa-v3-large-MNLI"] = {"preds": dv3_preds, "probs": dv3_probs}

all_p_values = []
p_value_labels = []
results = {
    "task": "R11: NLI verifier combo BH-corrected significance",
    "generator": "Mistral-7B-Instruct-v0.3",
    "dataset": "ProofWriter-D5-600",
    "n": n,
    "sc_baseline": round(sc_acc, 4),
    "sc_correct_count": int(sum(sc_correct)),
    "verifiers": {},
}

for vname, vdata in verifiers_data.items():
    v_correct = [vdata["preds"][pid] == gt[pid] for pid in pids]
    vresult = {
        "standalone_accuracy": round(sum(v_correct) / n, 4),
        "standalone_correct": int(sum(v_correct)),
        "combo": {},
    }
    for w in WEIGHTS:
        combo_answers = []
        for pid in pids:
            sv = mistral_votes.get(pid, {})
            np_ = vdata["probs"][pid]
            combined = {c: sv.get(c, 0) + w * np_.get(c, 0) for c in CLASSES}
            combo_answers.append(max(CLASSES, key=lambda x: combined[x]))
        combo_correct = [ca == gt[pid] for ca, pid in zip(combo_answers, pids)]
        combo_acc = sum(combo_correct) / n
        delta = combo_acc - sc_acc
        p, b, c = mcnemar_exact(sc_correct, combo_correct)
        vresult["combo"][f"w{w}"] = {
            "accuracy": round(combo_acc, 4),
            "correct": int(sum(combo_correct)),
            "delta_pp": round(delta * 100, 2),
            "mcnemar_b": int(b),
            "mcnemar_c": int(c),
            "mcnemar_p": round(p, 6),
        }
        all_p_values.append(p)
        p_value_labels.append(f"{vname}_w{w}")
    results["verifiers"][vname] = vresult

# Ensembles
vnames = list(verifiers_data.keys())
for ens_name, ens_key in [("three_verifier_avg", "avg"), ("three_verifier_majority", "majority")]:
    results[ens_name] = {}
    for w in WEIGHTS:
        combo_answers = []
        for pid in pids:
            sv = mistral_votes.get(pid, {})
            if ens_key == "avg":
                avg_nli = {}
                for c in CLASSES:
                    avg_nli[c] = sum(verifiers_data[vn]["probs"][pid].get(c, 0) for vn in vnames) / len(vnames)
                combined = {c: sv.get(c, 0) + w * avg_nli[c] for c in CLASSES}
            else:
                nli_votes = {c: 0 for c in CLASSES}
                for vn in vnames:
                    nli_votes[verifiers_data[vn]["preds"][pid]] += 1
                combined = {c: sv.get(c, 0) + w * nli_votes[c] for c in CLASSES}
            combo_answers.append(max(CLASSES, key=lambda x: combined[x]))
        combo_correct = [ca == gt[pid] for ca, pid in zip(combo_answers, pids)]
        combo_acc = sum(combo_correct) / n
        delta = combo_acc - sc_acc
        p, b, c = mcnemar_exact(sc_correct, combo_correct)
        results[ens_name][f"w{w}"] = {
            "accuracy": round(combo_acc, 4),
            "correct": int(sum(combo_correct)),
            "delta_pp": round(delta * 100, 2),
            "mcnemar_b": int(b),
            "mcnemar_c": int(c),
            "mcnemar_p": round(p, 6),
        }
        all_p_values.append(p)
        p_value_labels.append(f"{ens_name}_w{w}")

# BH correction
adjusted = bh_correction(all_p_values)
bh_results = []
for label, raw_p, adj_p in zip(p_value_labels, all_p_values, adjusted):
    bh_results.append({
        "test": label,
        "raw_p": round(raw_p, 6),
        "bh_adjusted_p": round(adj_p, 6),
        "significant_005": bool(adj_p < 0.05),
        "significant_010": bool(adj_p < 0.10),
    })

results["bh_correction"] = {
    "n_tests": len(all_p_values),
    "method": "Benjamini-Hochberg",
    "results": bh_results,
}

n_sig = sum(1 for r in bh_results if r["significant_005"])
n_sig10 = sum(1 for r in bh_results if r["significant_010"])
results["summary"] = {
    "n_significant_005": n_sig,
    "n_significant_010": n_sig10,
    "n_tests": len(all_p_values),
    "conclusion": f"{n_sig}/{len(all_p_values)} significant at BH alpha=0.05, {n_sig10}/{len(all_p_values)} at BH alpha=0.10"
}

with open(OUTPUT, "w") as f:
    json.dump(results, f, indent=2, cls=NumpyEncoder)
print(f"Saved to {OUTPUT}")
print(f"Summary: {results['summary']['conclusion']}")
PYEOF

